  + date
  + method
}

class Contract {
  + signingDate
  + billingFrequency
}

class Invoice {
  + amount
  + date
}

class ClaimCase {
  + status
}

class Estimator {
  + name
  + expertise
}

class EstimatorReport {
  + content
  + date
}

class CompensationDecision {
  + eligibleCosts
}

class Compensation {
  + amount
  + date
}

Customer "1" -- "1" Broker : is assigned to
Customer "1" -- "*" Offer : receives
Customer "1" -- "*" Contract : signs
Customer "1" -- "0..*" ClaimCase : files
Customer "1" -- "1" Compensation : receives
Broker "1" -- "*" Customer : manages
HeadOffice -- "*" Broker : employs
HeadOffice -- "*" Estimator : employs
Contract "1" -- "1" InsuranceProduct : based on
Contract "1" -- "1..*" Invoice : generates
Contract "1" -- "0..*" ClaimCase : covers
ClaimCase "1" -- "1..*" EstimatorReport : evaluated by
ClaimCase "1" -- "1" CompensationDecision : results in
ClaimCase "1" -- "0..*" Compensation : results in
Estimator "1" -- "*" EstimatorReport : issues

@enduml

